<script setup lang="ts">
import type { MulticaIssue, MulticaAgent } from '../services/multica.service';
import type { LocalConversation } from '../services/byok.service';
import LoadingIndicator from './LoadingIndicator.vue';
const props = defineProps<{ service:'multica'|'deepseek'; selectedId:string; issues:MulticaIssue[]; agents:MulticaAgent[]; conversations:LocalConversation[]; disabled:boolean; connected:boolean; loading:boolean; error:string; commentsLoading?:boolean }>();
const emit = defineEmits<{ new:[]; selectIssue:[issue:MulticaIssue]; selectConversation:[id:string]; deleteConversation:[id:string]; retry:[] }>();
import { ref } from 'vue';
const confirming = ref('');
function remove(id:string) { if (confirming.value !== id) { confirming.value=id; return; } confirming.value=''; emit('deleteConversation',id); }
const statusNames:Record<string,string>={backlog:'待处理',todo:'待处理',in_progress:'进行中',in_review:'待审核',done:'已完成',cancelled:'已取消',canceled:'已取消'};
function status(issue:MulticaIssue) { return statusNames[issue.status_category || ''] || statusNames[issue.status || ''] || issue.status || '未知'; }
function color(issue:MulticaIssue) { const s=status(issue); return s==='待审核'?'review':s==='已完成'||s==='完成'?'done':s==='待处理'?'pending':''; }
</script>
<template>
  <aside class="side-panel"><button class="new-button" type="button" :disabled="disabled || (service==='multica' && !connected)" @click="emit('new')"><span>＋</span> 新会话</button><div class="session-header"><strong>最近会话</strong><small>按服务分类</small></div><div class="session-list"><div class="section-label">Multica <small>最近 50 条</small></div><button v-for="issue in issues" :key="issue.id" type="button" class="session-item" :class="{chosen:service==='multica' && selectedId===issue.id}" :disabled="disabled" @click="emit('selectIssue',issue)"><span class="session-top"><span>{{ issue.identifier || '会话' }}</span><LoadingIndicator v-if="service==='multica' && selectedId===issue.id && commentsLoading" label="加载中" /><span v-else class="session-status" :class="color(issue)">{{ status(issue) }}</span></span><strong>{{ issue.title }}</strong><small>{{ agents.find(a=>a.id===issue.assignee_id)?.name || '未分配或不可见' }}</small></button><p v-if="loading" class="side-loading"><LoadingIndicator label="正在加载会话" /></p><p v-if="error" class="side-error" role="alert">{{ error }} <button type="button" @click="emit('retry')">重试</button></p><p v-else-if="!issues.length && !loading" class="empty">{{ connected ? '暂无会话' : '未连接 Multica' }}</p><div class="section-label">DeepSeek <small>本机会话</small></div><div v-for="chat in conversations" :key="chat.id" class="local-row" :class="{chosen:service==='deepseek' && selectedId===chat.id}"><button class="session-item local-item" type="button" :disabled="disabled" @click="emit('selectConversation',chat.id)"><strong>{{ chat.title }}</strong><small>{{ chat.model }}</small></button><button class="delete" type="button" :disabled="disabled" :aria-label="confirming===chat.id?'确认删除会话':'删除会话'" @click="remove(chat.id)">{{ confirming===chat.id?'确认删除':'×' }}</button></div><p v-if="!conversations.length" class="empty">暂无本地会话</p></div></aside>
</template>
<style scoped>
.side-panel{width:248px;flex:none;min-height:0;padding:14px;display:flex;flex-direction:column;border:1px solid var(--border,#e4e9f1);border-radius:16px;background:var(--panel,#fff);box-shadow:0 4px 20px #0000000a;box-sizing:border-box}.new-button{width:100%;padding:12px;border:1px solid #a5d9ef;border-radius:10px;text-align:left;color:var(--text,#26334b);font:inherit;font-weight:650;background:linear-gradient(110deg,#63beee29,#9d8bf417);cursor:pointer}.new-button span{color:#6999e6;font-size:18px;margin-right:6px}.session-header{display:flex;justify-content:space-between;align-items:center;margin:16px 4px 8px;font-size:13px}.session-header small,.section-label small{color:var(--muted,#a2aec0);font-size:10px}.session-list{flex:1;overflow:auto;min-height:0;display:flex;flex-direction:column;gap:4px}.section-label{display:flex;justify-content:space-between;margin:9px 9px 2px;font-size:10px;color:var(--muted,#9aa7ba);font-weight:650}.session-item{width:100%;display:flex;flex-direction:column;gap:4px;text-align:left;background:transparent;border:1px solid transparent;border-radius:8px;padding:9px;color:var(--text,#26334b);font:inherit;cursor:pointer}.session-item:hover,.local-row:hover{background:var(--surface,#f4f6fb)}.session-item.chosen,.local-row.chosen{background:#6f67e817;border-color:#6f67e824}.session-top{display:flex;justify-content:space-between;color:#998ff1;font-size:10px}.session-status,.session-item small{color:#9aa7ba}.session-status.review{color:#b77912}.session-status.done{color:#16835a}.session-status.pending{color:#d34545}.session-item strong{font-size:12px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.session-item small{font-size:10px}.side-loading,.side-error,.empty{padding:4px 9px;font-size:11px;margin:0}.empty{color:var(--muted,#94a3b8)}.side-error{color:#b45309;overflow-wrap:anywhere}.side-error button,.delete{border:0;background:transparent;color:#7569ec;cursor:pointer}.local-row{display:flex;align-items:center;border:1px solid transparent;border-radius:8px}.local-item{flex:1;min-width:0}.delete{padding:7px;font-size:11px;color:var(--muted,#94a3b8)}button:disabled{opacity:.5;cursor:not-allowed}@media(max-width:850px){.side-panel{width:190px}}
</style>
